PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?lossReserveAmount
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:soldByAgent ?agent ;
            in:policyNumber ?policyNumber .

    ?agent a in:Agent ;
           in:agentId ?agentId .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?claim a in:Claim ;
           in:against ?coverage ;
           in:claimNumber ?claimNumber ;
           in:hasLossReserve ?lossReserve .

    ?lossReserve a in:LossReserve ;
                 in:lossReserveAmount ?lossReserveAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?agentId
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:soldByAgent ?agent .
    ?agent a in:Agent ;
           in:agentId ?agentId .
  }
}

PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?policyNumber (AVG(?daysToSettle) AS ?averageDaysToSettle)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimOpenDate ?openDate ;
           in:claimCloseDate ?closeDate ;
           in:against ?coverage .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber .

    BIND( (xsd:dateTime(?closeDate) - xsd:dateTime(?openDate)) / "P1D"^^xsd:dayTimeDuration AS ?daysToSettle )
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber
       (SUM(?lossComponent) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:against ?pcd .

    ?pcd in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber .

    {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?amt .
      BIND(xsd:decimal(?amt) AS ?lossComponent)
    }
    UNION
    {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?amt .
      BIND(xsd:decimal(?amt) AS ?lossComponent)
    }
    UNION
    {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?amt .
      BIND(xsd:decimal(?amt) AS ?lossComponent)
    }
    UNION
    {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?amt .
      BIND(xsd:decimal(?amt) AS ?lossComponent)
    }
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:hasExpenseReserve ?expenseReserve .
    ?expenseReserve in:expenseReserveAmount ?expenseReserveAmount .
  }
}
ORDER BY ?claimNumber
